const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const pl=(n,f)=>{const a=Math.abs(n)%100,b=a%10;return f[a>10&&a<20?2:b===1?0:b>1&&b<5?1:2]};
const VW=["голос","голоса","голосов"];
const HIDDEN=[]; // скрытые новости: убрать id из списка, чтобы вернуть
function hideItems(){for(let i=NEWS.length-1;i>=0;i--)if(HIDDEN.includes(NEWS[i].id))NEWS.splice(i,1);for(let i=STORIES.length-1;i>=0;i--)if(HIDDEN.includes(STORIES[i].id))STORIES.splice(i,1)}
const VOTING=false; // голосование на паузе: включить — поставить true
const FLAGS=[[/РФ|Росси[яиюей]/,"🇷🇺"],[/Узбекистан[а-я]*/,"🇺🇿"],[/Дуба[йеюя]|ОАЭ/,"🇦🇪"],[/Казахстан[а-я]*/,"🇰🇿"]];
function flagify(t){if(typeof t!=="string")return t;let r=t;for(const [re,f] of FLAGS){r=r.replace(new RegExp("(^|[^А-Яа-яЁё🇦-🇿])("+re.source+")(?![А-Яа-яЁё])","gu"),(m,a,w)=>a+f+"\u00a0"+w)}return r}
function flagifyNews(){NEWS.forEach(n=>{["title","desc","short"].forEach(k=>n[k]=flagify(n[k]));["full","ingr"].forEach(k=>{if(n[k])n[k]=n[k].map(flagify)});if(n.wins)n.wins=n.wins.map(w=>w.map(flagify))})}
let myVote=null, tallies={}, live=false, db=null, uid=null, busy=false, readOnly=false, refreshModal=null;
try{const v=localStorage.getItem("de-vote"); if(byIdSafe(v)) myVote=v}catch(e){}
function byIdSafe(id){return NEWS.find(n=>n.id===id)}
function counts(){return live?tallies:(myVote?{[myVote]:1}:{})}
function renderVotes(){
  const c=counts(), total=Object.values(c).reduce((a,b)=>a+b,0), max=Math.max(1,...Object.values(c));
  const mine=myVote&&byId(myVote);
  $("#cartCount").textContent=mine?mine.name:"—";
  document.querySelectorAll("[data-votes]").forEach(el=>{const k=c[el.dataset.votes]||0;el.textContent=k?"🔥 "+k:""});
  document.querySelectorAll("[data-card]").forEach(el=>{const m=el.dataset.card===myVote;el.classList.toggle("mine",m);const ch=el.querySelector(".choose");if(ch)ch.textContent=m?"Ваш голос ✓":"Выбрать"});
  const sorted=NEWS.map((n,i)=>({n,i,k:c[n.id]||0})).sort((a,b)=>b.k-a.k||a.i-b.i);
  const leadK=sorted[0].k;
  $("#rows").innerHTML=sorted.map((r,i)=>`<button class="row${r.k&&r.k===leadK?" lead":""}${r.n.id===myVote?" me":""}" data-open="${r.n.id}">
    <span class="rk">${r.k&&r.k===leadK?"🏆":i+1}</span>${art(r.n)}
    <span class="nm"><b>${esc(r.n.name)}<small>${r.n.brand==="dodo"?"Додо Пицца":"Дринкит"}</small>${r.n.id===myVote?"<small>ваш голос</small>":""}</b><span class="bar"><i style="width:${r.k/max*100}%"></i></span></span>
    <span class="ct">${r.k}</span></button>`).join("");
  $("#boardSub").textContent=total?`Всего ${total} ${pl(total,VW)} · один голос на человека`:"Голосов пока нет. Откройте любую новость и станьте первым.";
  $("#boardNote").textContent=live?(readOnly?"У вас доступ только для просмотра: результаты видны, голосовать нельзя.":"Счёт обновляется в реальном времени."):"Сейчас голос сохраняется только у вас. Общий подсчёт работает, когда страница открыта в Claude под вашим аккаунтом.";
  if(refreshModal) refreshModal();
}
async function castVote(id){
  if(readOnly){toast("Голосовать можно с доступом «Contributor» и выше");return}
  if(busy) return; const next=myVote===id?null:id;
  if(live){
    busy=true;
    try{const ref=db.doc("votes/"+uid); if(next) await ref.set({id:next,at:Date.now()}); else await ref.delete(); myVote=next}
    catch(e){busy=false; if(e&&e.code==="invalid_argument"){readOnly=true;toast("Голос не сохранён: у вас доступ только для просмотра")}else toast("Не получилось сохранить голос. Попробуйте ещё раз"); renderVotes(); return}
    busy=false;
  } else { myVote=next; try{next?localStorage.setItem("de-vote",next):localStorage.removeItem("de-vote")}catch(e){} }
  renderVotes(); toast(next?"Голос принят!":"Голос отменён");
}
async function initVotes(){
  if(!window.claude||!window.claude.use) return;
  try{
    const [d,u]=await Promise.all([claude.use("db"),claude.use("user")]);
    uid=u?await u.id():null;
    if(!d||!uid) return;
    db=d;
    if(u.can){const c=await u.can("data.write"); if(c===false) readOnly=true}
    db.collection("votes").onSnapshot(snap=>{
      const t={}; let mine=null;
      snap.docs.forEach(x=>{const v=(x.data()||{}).id; if(byIdSafe(v)){t[v]=(t[v]||0)+1; if(x.id===uid) mine=v}});
      tallies=t; myVote=mine; live=true; renderVotes();
    },()=>{live=false;renderVotes()});
  }catch(e){}
}
const byId=id=>NEWS.find(n=>n.id===id);
