  $("#logoName").hidden=true; $("#logoMark").toggleAttribute("hidden",true); $("#ddLogo").hidden=b!=="dodo"; $("#dkLogo").hidden=b!=="drinkit"; $("#rdLogo").hidden=!(b==="read"||b==="kitchen");
  $("#reader").hidden=b!=="read"; if(b==="read"&&!$("#reader").childElementCount) renderReader();
  $("#kitchen").hidden=b!=="kitchen"; if(b==="kitchen"&&!$("#kitchen").childElementCount) renderKitchen();
