function renderDodo(){
  $("#b2b-grid").innerHTML=trackingCards();
  const dodo=NEWS.filter(n=>n.category==="launch");
  const wins=n=>n.wins?`<span class="wins">${n.wins.map(w=>`<span class="win"><b>🏆 ${esc(w[0])}</b><span>${esc(w[1])} — ${esc(w[2])}</span></span>`).join("")}</span>`:"";
  const pic=n=>deviceArt(n)||((CUTS[n.art]||IMGS[n.art])?`<img data-art="${n.art}" src="${CUTS[n.art]||IMGS[n.art]}" alt="${esc(n.title)}" loading="lazy">`:art(n));
  $("#pizza-grid").innerHTML=dodo.map(n=>n.wide?`<button class="prod wide tone-${n.tone||"plain"}" data-open="${n.id}" data-card="${n.id}">
    <span class="badge">${esc(n.badge[1].toLowerCase())}</span>
    <span class="pic">${pic(n)}<span class="vchip" data-votes="${n.id}"></span></span>
    <span class="txt"><h3>${esc(n.name)}</h3><p class="hl">${esc(n.desc)}</p>${wins(n)}<span class="pill">${esc(n.price)}</span></span></button>`
  :`<button class="prod tone-${n.tone||"plain"}" data-open="${n.id}" data-card="${n.id}">
    <span class="badge">${esc(n.badge[1].toLowerCase())}</span>
    <span class="pic">${pic(n)}<span class="vchip" data-votes="${n.id}"></span></span>
    <h3>${esc(n.name)}${n.badge[0]==="spicy"?'<span class="pepper" aria-label="острое">🌶</span>':""}</h3>
    <p class="hl">${esc(n.title)}</p>
    <span class="pill">${esc(n.price)}</span></button>`).join("");
  $("#often-list").innerHTML=["speed","b2b","pickup","game"].map(byId).map(n=>`<button data-open="${n.id}">${art(n)}<div><b>${esc(n.name)}</b><span>${esc(n.price)}</span></div></button>`).join("");
}
function renderDrinkit(){
  $("#drink-grid").innerHTML=NEWS.filter(n=>n.brand==="drinkit").sort((a,b)=>Number(["smart","cv"].includes(a.id))-Number(["smart","cv"].includes(b.id))).map(n=>`<button class="drink${n.wide?" wide":""}" data-open="${n.id}" data-card="${n.id}">
    <div class="pic" style="background:${n.bg}">${art(n)}<span class="chip">${esc(n.chip)}</span><span class="vchip" data-votes="${n.id}"></span></div>
    <div class="body"><h3>${esc(n.name)}</h3><p class="hl">${esc(n.title)}</p><p class="desc">${esc(n.desc)}</p>${n.wins?`<div class="dwins">${n.wins.map(w=>`<span><b>${esc(w[0])}</b>${esc(w[1])} · ${esc(w[2])}</span>`).join("")}</div>`:""}
    <div class="foot"><span class="plus" aria-hidden="true">+</span></div></div></button>`).join("");
}


