function bindStack(){
  document.querySelectorAll('[data-ks]').forEach(b=>b.onclick=()=>{
    const k=b.dataset.ks,o=k==='p'?'d':'p';
    if(KSHOW[k]&&!KSHOW[o]){KSHOW[o]=true}else KSHOW[k]=!KSHOW[k];
    $("#kStack").outerHTML=stackChart();
    document.querySelectorAll('[data-ks]').forEach(x=>x.setAttribute('aria-pressed',KSHOW[x.dataset.ks]));
    $("#kStackNote").textContent=KSHOW.p&&KSHOW.d?'':KSHOW.p?'Показана только Додо Пицца':'Показан только Дринкит — шкала своя, в млрд ₽';
  });
}
function lineChart(){
  const a=KD.dig21,ms=KD.dig21m,W=820,H=210,Lp=40,R=58,T=16,B=28,lo=.87,hi=.95,n=a.length;
  const x=i=>Lp+i*(W-Lp-R)/(n-1),y=v=>T+(H-T-B)*(hi-v)/(hi-lo);
  let g='';[.87,.89,.91,.93,.95].forEach(t=>{g+=`<line x1="${Lp}" x2="${W-R}" y1="${y(t)}" y2="${y(t)}" stroke="#ececf1"/><text x="${Lp-8}" y="${y(t)+4}" text-anchor="end" font-size="11" fill="#6b6e78">${Math.round(t*100)}%</text>`});
  const d=a.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1)).join(' ');
  g+=`<path d="${d} L${x(n-1)} ${H-B} L${x(0)} ${H-B} Z" fill="#ed6e2d" opacity=".12"/><path d="${d}" fill="none" stroke="#ed6e2d" stroke-width="2.5" stroke-linejoin="round"/>`;
  ms.forEach((m,i)=>{if(i===n-1||(/-(01|05|09)$/.test(m)&&x(n-1)-x(i)>=64)){const last=i===n-1;g+=`<text x="${x(i)}" y="${H-8}" text-anchor="middle" font-size="11" font-weight="${last?800:500}" fill="${last?'#ed6e2d':'#6b6e78'}">${mlab(m)}</text>`}
    g+=`<rect x="${x(i)-(W-Lp-R)/(n-1)/2}" y="${T}" width="${(W-Lp-R)/(n-1)}" height="${H-B-T}" fill="transparent" data-tip="<b>${mlab(m)}</b> · ${pct(a[i])}"/>`});
  g+=`<circle cx="${x(n-1)}" cy="${y(L(a))}" r="6" fill="#ed6e2d" stroke="#fff" stroke-width="2.5"/><text x="${x(n-1)+12}" y="${y(L(a))+5}" font-size="14" font-weight="800" fill="#111">${pct(L(a))}</text>`;
  return `<svg class="kch" viewBox="0 0 ${W} ${H}" role="img" aria-label="Доля digital в выручке по месяцам">${g}</svg>`;
}
