 return `<div class="tg-kpis">${cards.map(([title,value,previous,delta])=>`<article class="tg-kpi"><h3>${title}</h3><b>${value}</b><p>${previous}</p><span>${delta}</span></article>`).join('')}</div><div class="tg-legend"><span><i class="sep"></i>Сентябрь</span><span><i class="oct"></i>Октябрь</span></div><div class="tg-charts"><article class="tg-chart"><header><h3>Время доставки</h3><p>Минуты и секунды · меньше — быстрее</p></header>${group('С умным трекингом',bar('sep',2111,'35:11',2400)+bar('oct',2130,'35:30',2400))}${group('Без умного трекинга',bar('sep',2033,'33:53',2400)+bar('oct',2059,'34:19',2400))}${axis(['0','10','20','30','40 мин'])}<p class="tg-takeaway">В октябре доставка с УТ дольше на <strong>1 минуту 11 секунд</strong>.</p></article><article class="tg-chart"><header><h3>Промо за опоздание</h3><p>Доля заказов с промо · количество под процентом</p></header>${group('С умным трекингом',bar('sep',4.4,'4,4%',6,'7 832')+bar('oct',5.26,'5,26%',6,'18 149'))}${group('Без умного трекинга',bar('sep',3.36,'3,36%',6,'160 852')+bar('oct',3.76,'3,76%',6,'193 548'))}${axis(['0','1,5','3','4,5','6%'])}<p class="tg-takeaway">Разница в октябре — <strong>1,5 п.п.</strong> между группами.</p></article></div><p class="tg-caption">Состав групп отличается: сравнение само по себе не доказывает влияние УТ. Причины отставания и следующие шаги — ниже.</p>`;
