function openItem(id){
  const n=byId(id); if(!n) return;
  const cur=document.documentElement.dataset.brand||"dodo";
  if(n.brand!=="all"&&n.brand!==cur&&!(cur==="kitchen"&&n.category==="tracking")) setBrand(n.brand);
  const isD=n.brand==="all"?cur==="dodo":n.brand==="dodo"; let mode="short";
  const initials=n.author?n.author.split(" ").map(w=>w[0]).join(""):"?";
  const L=$("#layer");
  L.innerHTML=`<div class="overlay" data-close><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(n.name)}">
    <button class="close" data-close aria-label="Закрыть">×</button>
    <div class="m-pic" style="${n.brand==="dodo"?"background:#fff":"background:"+n.bg}">${deviceArt(n)?deviceArt(n):isD&&IMGS[n.art]?`<img src="${IMGS[n.art]}" alt="Как это выглядит в продукте: ${esc(n.title)}">`:art(n)}${n.link?`<a class="bubble" href="${n.link}" target="_blank" rel="noopener">${n.linkBubble||"🍕 Открыть презу?"}</a>`:""}</div>
    <div class="m-info">
      <h3>${esc(n.name)}</h3>
      <p class="hl">${esc(n.title)}</p>
      <div class="seg" role="group" aria-label="Подробность"><button id="segS" aria-pressed="true"><span class="lg">${isD?"Маленькая · коротко":"S · коротко"}</span><span class="sm">Коротко</span></button><button id="segF" aria-pressed="false"><span class="lg">${isD?"Большая · целиком":"L · целиком"}</span><span class="sm">Целиком</span></button></div>
      <div class="m-text" id="mText"></div>
      <div class="ingr" id="ingr">${n.ingr.map((t,i)=>`<button aria-pressed="true" data-i="${i}">${esc(t)} <span class="x" aria-hidden="true">×</span></button>`).join("")}</div>
      <p class="ingr-note">${isD?"Ингредиенты можно убрать, как в настоящем меню. Цифры от этого не изменятся.":"Главное в новости. Нажмите, чтобы скрыть пункт."}</p>
      <div class="author"><span class="ava">${esc(initials)}</span><div>${n.author?`<b>${esc(n.author)}</b><br><code>${esc(n.email)}</code>`:`<b>Автор уточняется</b>`}</div></div>
      <div class="m-actions">
        ${VOTING?`<button class="add" id="addBtn"></button><p class="vote-note" id="voteNote"></p>`:""}
        ${n.link?`<a class="${VOTING?"link":"add cta"}" href="${n.link}" target="_blank" rel="noopener">${n.linkLabel||"Открыть презентацию в Figma"} ↗</a>`:""}
      </div>
    </div></div></div>`;
  const txt=()=>{$("#mText").innerHTML=(mode==="short"?[n.short]:n.full).map(p=>`<p>${esc(p)}</p>`).join("");$("#segS").setAttribute("aria-pressed",mode==="short");$("#segF").setAttribute("aria-pressed",mode!=="short")};
  const addLbl=()=>{const b=$("#addBtn"); if(!b){refreshModal=null;return} const inC=myVote===n.id; b.classList.toggle("in",inC);
    b.textContent=inC?"Ваш голос ✓ · отменить":(myVote?"Перенести голос сюда":(isD?"Выбрать · отдать голос":"Выбрать · отдать голос"));
    $("#voteNote").textContent="Один голос на человека, его можно перенести. Итоги покажем в конце месяца."};
  refreshModal=addLbl; txt();addLbl();
  $("#segS").onclick=()=>{mode="short";txt()};$("#segF").onclick=()=>{mode="full";txt()};
  $("#ingr").onclick=e=>{const b=e.target.closest("button");if(b)b.setAttribute("aria-pressed",b.getAttribute("aria-pressed")==="false")};
  {const ab=$("#addBtn"); if(ab) ab.onclick=()=>castVote(n.id);}
  L.querySelector(".overlay").addEventListener("click",e=>{if(e.target.hasAttribute("data-close"))closeLayer()});
  $(".close").focus();
}
function closeLayer(){refreshModal=null;$("#layer").innerHTML="";clearTimeout(svT);cancelAnimationFrame(svRaf)}

/* ================== STORIES VIEWER ================== */
let svT,svRaf;
function openStory(i){
  const order=[...$("#stories").querySelectorAll("[data-story]")].map(b=>+b.dataset.story);
  let pos=order.indexOf(i);
  const show=()=>{
    const s=STORIES[order[pos]];
    $("#layer").innerHTML=`<div class="sv"><div class="sv-card" style="background:${s.bg}">
      <div class="sv-bars">${order.map((_,k)=>`<i><b style="width:${k<pos?100:0}%"></b></i>`).join("")}</div>
      <div class="sv-top"><span>${esc(s.tag||(s.brand==="dodo"?"Додо Пицца":"Дринкит"))} · октябрь 2026</span><button aria-label="Закрыть" id="svX">×</button></div>
      <button class="sv-tap l" aria-label="Назад"></button><button class="sv-tap r" aria-label="Дальше"></button>
      <div class="sv-main"><div class="big">${esc(s.big)}</div><div class="cap">${esc(s.cap)}</div><div class="det">${esc(s.det)}</div></div>
      <button class="sv-cta" id="svGo">${s.k?"Подробнее в разделе Аналитика →":"Открыть позицию в меню"}</button></div></div>`;
    $("#svX").onclick=closeLayer;
    $(".sv-tap.l").onclick=()=>{if(pos>0){pos--;show()}};
    $(".sv-tap.r").onclick=next;
    $("#svGo").onclick=()=>{clearTimeout(svT);cancelAnimationFrame(svRaf);if(s.k){closeLayer();setBrand("kitchen",true);setTimeout(()=>{const t=document.getElementById(s.k);if(t)t.scrollIntoView({behavior:"smooth",block:"start"})},450)}else openItem(s.id)};
    const bar=$(".sv-bars").children[pos].firstElementChild; const t0=performance.now(), D=5000;
    cancelAnimationFrame(svRaf);
    const tick=t=>{const p=Math.min(1,(t-t0)/D);bar.style.width=p*100+"%";if(p<1)svRaf=requestAnimationFrame(tick);else next()};
    svRaf=requestAnimationFrame(tick);
  };
  const next=()=>{cancelAnimationFrame(svRaf);if(pos<order.length-1){pos++;show()}else closeLayer()};
  show();
}

/* ================== MY VOTE ================== */
function openCart(){
  const n=myVote&&byId(myVote);
  if(!n){document.getElementById("pizza").scrollIntoView({behavior:"smooth"});toast("Вы ещё не голосовали — выберите новость в меню");return}
  openItem(n.id);
}

/* ================== EVENTS ================== */
document.addEventListener("click",e=>{
  const analyticsLink=e.target.closest('[data-analytics-target]');
  if(analyticsLink){
    e.preventDefault();setBrand('kitchen',false);
    const target=document.getElementById(analyticsLink.dataset.analyticsTarget);
    if(target){target.setAttribute('tabindex','-1');requestAnimationFrame(()=>{target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});target.focus({preventScroll:true});});}
    return;
  }
  const readerLink=e.target.closest("[data-read-target]");
  if(readerLink){
    e.preventDefault();
    setBrand("read",false);
    const target=document.getElementById(readerLink.dataset.readTarget);
    if(target){
      target.querySelectorAll("details").forEach(detail=>detail.open=true);
      target.setAttribute("tabindex","-1");
      const reduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      requestAnimationFrame(()=>{target.scrollIntoView({behavior:reduced?"auto":"smooth",block:"start"});target.focus({preventScroll:true});});
    }
    return;
  }
  const o=e.target.closest("[data-open]"); if(o){openItem(o.dataset.open);return}
  const s=e.target.closest("[data-story]"); if(s){openStory(+s.dataset.story);return}
  const g=e.target.closest("[data-go]"); if(g){e.preventDefault();setBrand(g.dataset.go,true)}
});
document.addEventListener("keydown",e=>{if(e.key==="Escape")closeLayer()});
$("#bDodo").onclick=()=>setBrand("dodo",true);
$("#bDrinkit").onclick=()=>setBrand("drinkit",true);
$("#bRead").onclick=()=>setBrand("read",true);
$("#bKit").onclick=()=>setBrand("kitchen",true);
document.addEventListener("click",e=>{if(e.target.closest("[data-kitchen]"))setBrand("kitchen",true)});
$("#cartBtn").onclick=openCart;

document.querySelectorAll('.track-card[data-open]').forEach(card=>{const n=byId(card.dataset.open),img=card.querySelector('img');if(n&&img&&deviceArt(n))img.outerHTML=deviceArt(n)});
hideItems();flagifyNews();renderDodo();renderDrinkit();renderPromo();renderVotes();if(VOTING)initVotes();
